type Expr interface{ Eval(*Context) (Value, error) }
type Num struct{ V Value }
func (n Num) Eval(*Context) (Value, error) { return n.V, nil }
type Add struct{ L, R Expr }
func (a Add) Eval(c *Context) (Value, error) {
    l, err := a.L.Eval(c)
    if err != nil { return nil, err }
    r, err := a.R.Eval(c)
    if err != nil { return nil, err }
    return add(l, r)
}

